# -*- coding=utf-8 -*-

import re

# -------------------
# a custom exception class
class MyError(Exception):
    pass

class Person:

    # constructor
    def __init__(self, first_name="x", last_name="x", age=0):
         # the first name must not be empty
        match = re.match(r"^\s*(\S+)\s*$", first_name)
        if not match:
            raise MyError("The first name cannot be empty")
        else:
            self.first_name = match.groups()[0]
        # the last name must not be empty
        match = re.match(r"^\s*(\S+)\s*$", last_name)
        if not match:
            raise MyError("The last name cannot be empty")
        else:
            self.name = match.groups()[0]
        # age must be valid
        match = re.match(r"^\s*(\d+)\s*$", str(age))
        if not match:
            raise MyError("age must be a positive integer")
        else:
            self.age = match.groups()[0]

    def __str__(self):
        return "[{0},{1},{2}]".format(self.first_name, self.last_name, self.age)

# ---------------------------------- main
# a Person object
try:
    p = Person("  Paul  ","  Langevin  ", 48)
    print "person={0}".format(p)
except MyError, error:
    print error
# another Person object
try:
    p = Person("  xx  ", "  yy  ", "  zz  ")
    print "person={0}".format(p)
except MyError, error:
    print error
# another person
try:
    p = Person()
    print "person={0}".format(p)
except MyError, error:
    print error
</code></pre> <p>Notes:</p> <ul> <li>lines 7-8: a MyError class derived from the Exception class. It adds no functionality to the latter. It is only there to provide a custom exception;</li> <li>Line 13: The constructor has default values for its parameters. Thus, the operation p = Person() is equivalent to p = Person("x", "x", 0);</li> <li>Lines 15–9: The first_name parameter is checked. It must not be empty. If it is, the MyError exception is thrown with an error message;</li> <li>Lines 21–25: Same for the last_name;</li> <li>lines 27–31: age verification;</li> <li>lines 33-34: the __str__ function replaces the method previously called identite;</li> <li>lines 38–42: instantiate a Person and display its identity;</li> <li>line 39: instantiation;</li> <li>line 40: display. The operation requires displaying the person p as a string. The Python interpreter then automatically calls the method p.__str__() if it exists. This method serves the same purpose as the toString() method in Java or .NET languages;</li> <li>lines 41–42: handling of a potential MyError exception. Then displays the error message associated with the exception;</li> <li>lines 44–48: same as above for a second instance of Person created with incorrect parameters;</li> <li>lines 50–54: same as above for a third person instantiated with default parameters.</li> </ul> Results <pre><code>person=[Paul,Langevin,48]
